export function isVerifiedPdf(url) {
  if (!url || typeof url !== 'string' || url.endsWith('.html') || url === '#') return false;
  const clean = '/' + url.replace(/^\//, '').split('?')[0].split('#')[0];
  return VERIFIED_PDFS.has(clean);
}
